    fun generated(base: String, dark: Boolean, style: ColorSchemeStyle): ColorScheme = when (style) {
        ColorSchemeStyle.NeutralSurfaces -> when (base) {
            "orange" -> if (dark) orangeNeutralSurfacesDark else orangeNeutralSurfacesLight
            "blue" -> if (dark) blueNeutralSurfacesDark else blueNeutralSurfacesLight
            "violet" -> if (dark) violetNeutralSurfacesDark else violetNeutralSurfacesLight
            "teal" -> if (dark) tealNeutralSurfacesDark else tealNeutralSurfacesLight
            "rose" -> if (dark) roseNeutralSurfacesDark else roseNeutralSurfacesLight
            "green" -> if (dark) greenNeutralSurfacesDark else greenNeutralSurfacesLight
            "amber" -> if (dark) amberNeutralSurfacesDark else amberNeutralSurfacesLight
            "slate" -> if (dark) slateNeutralSurfacesDark else slateNeutralSurfacesLight
            "hn" -> if (dark) hnNeutralSurfacesDark else hnNeutralSurfacesLight
            "hackerGreen" -> if (dark) hackerGreenNeutralSurfacesDark else hackerGreenNeutralSurfacesLight
            else -> error("Unknown generated color scheme: $base")
        }
        ColorSchemeStyle.Balanced -> when (base) {
            "orange" -> if (dark) orangeDark else orangeLight
            "blue" -> if (dark) blueDark else blueLight
            "violet" -> if (dark) violetDark else violetLight
            "teal" -> if (dark) tealDark else tealLight
            "rose" -> if (dark) roseDark else roseLight
            "green" -> if (dark) greenDark else greenLight
            "amber" -> if (dark) amberDark else amberLight
            "slate" -> if (dark) slateDark else slateLight
            "hn" -> if (dark) hnDark else hnLight
            "hackerGreen" -> if (dark) hackerGreenDark else hackerGreenLight
            else -> error("Unknown generated color scheme: $base")
        }
        ColorSchemeStyle.Vibrant -> when (base) {
            "orange" -> if (dark) orangeVibrantDark else orangeVibrantLight
            "blue" -> if (dark) blueVibrantDark else blueVibrantLight
            "violet" -> if (dark) violetVibrantDark else violetVibrantLight
            "teal" -> if (dark) tealVibrantDark else tealVibrantLight
            "rose" -> if (dark) roseVibrantDark else roseVibrantLight
            "green" -> if (dark) greenVibrantDark else greenVibrantLight
            "amber" -> if (dark) amberVibrantDark else amberVibrantLight
            "slate" -> if (dark) slateVibrantDark else slateVibrantLight
            "hn" -> if (dark) hnVibrantDark else hnVibrantLight
            "hackerGreen" -> if (dark) hackerGreenVibrantDark else hackerGreenVibrantLight
            else -> error("Unknown generated color scheme: $base")
        }
    }
